import os

# Check if lsof is available and look for deleted files
print("Checking for deleted but open files:")
result = subprocess.run(['lsof', '+L1'], capture_output=True, text=True)
if 'main.db-wal' in result.stdout or 'wal' in result.stdout.lower():
    print("Found WAL reference in lsof!")
