# Check /proc for any process that might have the file
print("\nChecking /proc/*/fd for WAL references:")
for pid_dir in os.listdir('/proc'):
    if pid_dir.isdigit():
        fd_dir = f'/proc/{pid_dir}/fd'
        if os.path.exists(fd_dir):
            try:
                for fd in os.listdir(fd_dir):
                    try:
                        link = os.readlink(f'{fd_dir}/{fd}')
                        if 'wal' in link.lower():
                            print(f"  PID {pid_dir}, FD {fd}: {link}")
                    except:
                        pass
            except:
                pass

